-- Version 9: real photographs, every one freely licensed and credited.
-- Photos come from Wikimedia Commons (the lead image of each item's Wikipedia article), kept only when the licence
-- is CC BY, CC BY-SA, CC0 or public domain. Each carries its author and licence, shown under the photo, as those
-- licences require. Photos that did not show their subject were left out (one meal photo for three dishes, a Gangaur
-- dance from Malwa, a Bhavai dance from Gujarat).
-- Earlier migrations have already run on the live site; never edit them, add a new file instead.

-- a photo on a fact card: {"src", "page" (the file's Commons page), "credit", "caption"}
ALTER TABLE facts ADD COLUMN image JSONB;
-- a few photos on each city's letter, same shape
ALTER TABLE cities ADD COLUMN photos JSONB NOT NULL DEFAULT '[]';

