  ('udaipur', 'A prince hides on Jag Mandir', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/JagMandir.jpg/960px-JagMandir.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Jag Mandir, the island palace. Photo: Philbrest, CC BY-SA 3.0, via Wikimedia Commons"}]'::jsonb),
