  ('udaipur', 'The Lake Palace is finished', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Udaipur_Lake_Palace.jpg/960px-Udaipur_Lake_Palace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "The Lake Palace on Lake Pichola. Photo: user:Flicka, CC BY-SA 3.0, via Wikimedia Commons"}]'::jsonb),
  ('udaipur', 'The Monsoon Palace', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/2/20/Monsoon_Palace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Sajjangarh, the Monsoon Palace. Photo: tommy, CC BY-SA 2.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'A trading post on the Hooghly', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/0/03/Kolkata_Map_1690.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "A trading post on the Hooghly. Photo: P.K.Niyogi, CC BY-SA 3.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'The Indian Museum opens', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Indian_Museum%2C_Courtyard%2C_Kolkata%2C_India.jpg/960px-Indian_Museum%2C_Courtyard%2C_Kolkata%2C_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "The courtyard of the Indian Museum. Photo: Vyacheslav Argenberg, CC BY 4.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'Dakshineswar Kali Temple', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Dakhineshwar_Temple_beside_the_Hoogly%2C_West_Bengal.JPG/960px-Dakhineshwar_Temple_beside_the_Hoogly%2C_West_Bengal.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Dakshineswar Kali Temple beside the Hooghly. Photo: Knath, CC BY-SA 3.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'The first trams', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/211_at_Esplanade.jpg/960px-211_at_Esplanade.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Tram 211 at Esplanade. Photo: Gupsag1998, CC0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'Howrah Bridge opens', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Howrah_bridge_at_night.jpg/960px-Howrah_bridge_at_night.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Howrah Bridge at night. Photo: Apoorva Karlekar, CC BY-SA 4.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'India''s first metro', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/ICF_MEDHA_MR-416.jpg/960px-ICF_MEDHA_MR-416.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "A Kolkata Metro train. Photo: SOUMYADEEP3716, CC BY-SA 4.0, via Wikimedia Commons"}]'::jsonb),
  ('udaipur', 'Work begins on the City Palace', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Udaipur_City_Palace.jpg/960px-Udaipur_City_Palace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "The City Palace above Lake Pichola. Photo: Henrik Bennetsen, CC BY-SA 2.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'No longer the capital', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Delhi_Durbar%2C_1911.jpg/960px-Delhi_Durbar%2C_1911.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "No longer the capital. Photo: Unknown photographer, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'A Nobel Prize for Tagore', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/1926_Rabindrath_Tagore.jpg/960px-1926_Rabindrath_Tagore.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Rabindranath Tagore in 1926. Photo: Georges Chevalier, CC BY 4.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'Calcutta becomes Kolkata', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Kolkata_maidan.jpg/960px-Kolkata_maidan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Calcutta becomes Kolkata. Photo: NalGup20, CC BY-SA 4.0, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'Durga Puja joins UNESCO''s list', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/%E0%A6%AC%E0%A6%BE%E0%A6%97%E0%A6%AC%E0%A6%BE%E0%A6%9C%E0%A6%BE%E0%A6%B0_%E0%A6%B8%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%AC%E0%A6%9C%E0%A6%A8%E0%A7%80%E0%A6%A8_%E0%A6%A6%E0%A7%81%E0%A6%B0%E0%A7%8D%E0%A6%97%E0%A7%8B%E0%A7%8E%E0%A6%B8%E0%A6%AC_%E0%A7%A8%E0%A7%A6%E0%A7%A7%E0%A7%AE.jpg/960px-%E0%A6%AC%E0%A6%BE%E0%A6%97%E0%A6%AC%E0%A6%BE%E0%A6%9C%E0%A6%BE%E0%A6%B0_%E0%A6%B8%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%AC%E0%A6%9C%E0%A6%A8%E0%A7%80%E0%A6%A8_%E0%A6%A6%E0%A7%81%E0%A6%B0%E0%A7%8D%E0%A6%97%E0%A7%8B%E0%A7%8E%E0%A6%B8%E0%A6%AC_%E0%A7%A8%E0%A7%A6%E0%A7%A7%E0%A7%AE.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Bagbazar Sarbojanin Durga Puja, 2018. Photo: Subhrajyoti07, CC BY-SA 4.0, via Wikimedia Commons"}]'::jsonb)
), before AS (
  SELECT e.id, to_jsonb(e) AS row, x.imgs FROM timeline_events e JOIN x ON x.city = e.city_id AND x.title = e.title WHERE e.images = '[]'::jsonb
), done AS (
  UPDATE timeline_events e SET images = b.imgs, status = 'needs_check', verified_by = NULL, verified_at = NULL, updated_at = now()
  FROM before b WHERE e.id = b.id RETURNING e.*
)
INSERT INTO content_log (user_id, action, entity, entity_id, before, after)
SELECT NULL, 'update', 'timeline', d.id::text, b.row, to_jsonb(d) FROM done d JOIN before b ON b.id = d.id;

